import{_ as a,C as o,o as r,c as i,E as s,a2 as n}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"恢复上下文，不等于恢复权限","description":"","frontmatter":{"title":"恢复上下文，不等于恢复权限","date":"2026-08-29","column":"digital-employee","category":"daily","article_type":"technical-analysis","edition":"research-center","research_question":"可恢复智能体应如何区分上下文重建权与当前执行权？","summary":"OpenAI Codex（代码智能体）的一项已合并变更表明，合格的完整状态快照可以恢复上下文连续性；但这份重建证据不能自动成为当前权限。可靠恢复需要把完整性、谱系与现行授权分成可独立核验的关口。","sources":["research/analysis/Q-20260829-01-reconstruction-authority-separate-from-execution-authority.md"],"item_id":"Q-20260829-01","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-29-restoring-context-does-not-restore-authority-cover-v2.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/digital-employee/2026-08-29-restoring-context-does-not-restore-authority.md","filePath":"zh/digital-employee/2026-08-29-restoring-context-does-not-restore-authority.md","lastUpdated":1788162175000}'),c={name:"zh/digital-employee/2026-08-29-restoring-context-does-not-restore-authority.md"};function l(d,e,p,h,u,m){const t=o("ArticleCover");return r(),i("div",null,[s(t,{image:"/assets/covers/daily-2026-08-29-restoring-context-does-not-restore-authority-cover-v2.png",kicker:"数字员工 · 每日研究",title:"恢复上下文，不等于恢复权限",summary:"OpenAI Codex（代码智能体）的一项已合并变更表明，合格的完整状态快照可以恢复上下文连续性；但这份重建证据不能自动成为当前权限。可靠恢复需要把完整性、谱系与现行授权分成可独立核验的关口。",version:"Q-20260829-01",status:"Daily Runtime V5 · 2026-08-29",languageHref:"/en/digital-employee/2026-08-29-restoring-context-does-not-restore-authority",languageLabel:"English"}),e[0]||(e[0]=n('<h1 id="恢复上下文-不等于恢复权限" tabindex="-1">恢复上下文，不等于恢复权限 <a class="header-anchor" href="#恢复上下文-不等于恢复权限" aria-label="Permalink to &quot;恢复上下文，不等于恢复权限&quot;">​</a></h1><p>可恢复智能体有一个容易被忽略的权限问题：一份持久状态可能足以告诉系统“上次做到哪里”，却不足以回答“现在还允许做什么”。如果把这两个问题合并，持久化本身就会成为一条隐式授权通道。</p><p>OpenAI Codex（代码智能体）的一项已合并变更提供了具体案例。嵌套执行体分叉后，即使关联任务消息已经不在存活历史中，只要仍有合格、完整且未被压缩边界淘汰的世界状态快照，系统就可以恢复上一轮设置与引用上下文。同时，裸露的轮次上下文、只含增量的状态以及已被压缩淘汰的完整快照都不能取得重建资格。</p><p>核心判断是：<strong>重建权与执行权必须分开。前者决定哪份持久证据可以恢复连续性，后者决定当前策略是否允许恢复出的状态影响能力与外部效果。</strong></p><h2 id="什么证据足以恢复连续性" tabindex="-1">什么证据足以恢复连续性 <a class="header-anchor" href="#什么证据足以恢复连续性" aria-label="Permalink to &quot;什么证据足以恢复连续性&quot;">​</a></h2><p>只接受仍存活的任务消息，看似最安全，却会错误丢弃分叉后仍然有效的完整状态。反过来，允许任意片段成为基线，又可能把缺字段、只含补丁或已失效的状态重新带回当前轮次。</p><p>合格的完整快照建立了中间边界：它必须表示一份完整基线，仍位于当前存活谱系内，并且没有被后续压缩所取代。负向测试在这里与正向恢复同样重要，因为它们明确说明哪些证据不会获得重建资格。</p><p>这套边界回答的是连续性问题。它可以证明系统没有凭空虚构缺失任务，也没有把局部补丁误当成完整世界；它仍不能证明快照里的每个字段在今天都正确。</p><h2 id="为什么重建资格不是执行许可" tabindex="-1">为什么重建资格不是执行许可 <a class="header-anchor" href="#为什么重建资格不是执行许可" aria-label="Permalink to &quot;为什么重建资格不是执行许可&quot;">​</a></h2><p>恢复出的偏好、引用和工作进度通常只是上下文。但只要某个字段能够改变工具、凭据范围、身份或外部效果，它就具有权限含义。此时，结构完整与谱系存活仍然不等于当前可用。</p><p>例如，快照创建后，管理员可能撤销了某项能力，资源可能已被删除，凭据范围也可能缩小。压缩边界只能说明这份状态在已展示的历史模型中没有被淘汰，不能替代对外部策略和资源现状的检查。</p><p>因此，恢复流程需要两道关口。第一道核验完整性与谱系，决定是否允许重建；第二道只针对会影响能力或效果的字段，重新绑定当前策略与资源状态。这样既不牺牲合法连续性，也不会让旧状态自动继承新权限。</p><h2 id="审计应保留三种身份" tabindex="-1">审计应保留三种身份 <a class="header-anchor" href="#审计应保留三种身份" aria-label="Permalink to &quot;审计应保留三种身份&quot;">​</a></h2><p>一个可信的恢复回执至少应分开记录三件事：哪份基线建立了上下文、它属于哪个谱系或代次，以及什么当前授权允许哪些恢复字段参与执行。</p><p>如果只记录“恢复成功”，运营者无法判断失败来自状态缺失、谱系过期还是权限撤销。若把授权决定写回原快照，又可能污染历史证据。更稳妥的方式是让基线保持不可变，再生成一份独立、带时间与策略版本的授权结果。</p><p>模式迁移也需要同样谨慎。旧快照升级到新模式时，转换可以补齐数据结构，却不应静默提升权限语义。任何新增的权限字段都应以当前策略重新求值。</p><h2 id="仍未证明的边界" tabindex="-1">仍未证明的边界 <a class="header-anchor" href="#仍未证明的边界" aria-label="Permalink to &quot;仍未证明的边界&quot;">​</a></h2><p>现有证据来自一个已合并实现及其维护者回归测试，没有独立复现。它不认证快照创建者，不证明跨主机一致性，也不覆盖并发破坏、重放攻击或外部资源撤销。</p><p>这并不削弱已证明的设计价值，而是限定正确的完成语言：系统可以声称“合格基线恢复了上下文”，只有在第二道关口产生新证据后，才能进一步声称“这些恢复字段获准参与当前执行”。</p><h2 id="开放问题" tabindex="-1">开放问题 <a class="header-anchor" href="#开放问题" aria-label="Permalink to &quot;开放问题&quot;">​</a></h2><p>工程团队仍需决定哪些字段必须重新授权、谱系代次如何跨模式迁移保持稳定，以及当结构有效的快照指向已撤销资源时应返回什么类型化证据。最重要的原则并不复杂：<strong>连续性来自持久证据，执行权来自当前决定；前者不能替代后者。</strong></p><p><strong>一手证据：</strong> <a href="https://github.com/openai/codex/commit/f9cdc90c2c4d38cd557deb933e592f0032a5ea6e" target="_blank" rel="noreferrer">OpenAI Codex 已合并提交 f9cdc90c</a>。该实现与测试支持有界的上下文重建结论，不证明通用授权安全。</p>',22))])}const y=a(c,[["render",l]]);export{g as __pageData,y as default};
